using System.ComponentModel.DataAnnotations;

namespace VitalTrek.API.IncidentResponse.Interfaces.Rest.Resources;

/// <summary>
///     Resource to record an evacuation action captured by the assigned field guide, possibly offline. ClientActionId is
///     generated by the client at capture time and reused by every retry; RecordedAt is the original capture moment.
/// </summary>
public record RecordEvacuationActionResource(
    [Required(ErrorMessage = "RequiredEvacuationClientActionId")] Guid ClientActionId,
    [Required(ErrorMessage = "RequiredEvacuationDescription")]
    [StringLength(500, MinimumLength = 1, ErrorMessage = "RequiredEvacuationDescription")] string Description,
    [StringLength(200, ErrorMessage = "EvacuationLocationTooLong")] string? Location,
    [Required(ErrorMessage = "RequiredEvacuationStatus")] string Status,
    [Required(ErrorMessage = "RequiredEvacuationRecordedAt")] DateTimeOffset RecordedAt);
